bool
parser_leak_add(enum parser_leak_types type, void *v)
{
#ifdef NO_LEAKS
    struct parser_leak_entry *entry;
    debug_decl(parser_leak_add, SUDOERS_DEBUG_PARSER);

    if (v == NULL)
        debug_return_bool(false);

    entry = calloc(1, sizeof(*entry));
    if (entry == NULL) {
        sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
        debug_return_bool(false);
    }
    switch (type) {
    case LEAK_PRIVILEGE:
        entry->u.p = v;
        break;
    case LEAK_CMNDSPEC:
        entry->u.cs = v;
        break;
    case LEAK_DEFAULTS:
        entry->u.d = v;
        break;
    case LEAK_MEMBER:
        entry->u.m = v;
        break;
    case LEAK_DIGEST:
        entry->u.dig = v;
        break;
    case LEAK_RUNAS:
        entry->u.rc = v;
        break;
    case LEAK_PTR:
        entry->u.ptr = v;
        break;
    default:
        free(entry);
        sudo_warnx("unexpected leak type %d", type);
        debug_return_bool(false);
    }
    entry->type = type;
    SLIST_INSERT_HEAD(&parser_leak_list, entry, entries);
    debug_return_bool(true);
#else
    return true;
#endif /* NO_LEAKS */
}

bool
parser_leak_remove(enum parser_leak_types type, void *v)
{
#ifdef NO_LEAKS
    struct parser_leak_entry *entry, *prev = NULL;
    debug_decl(parser_leak_remove, SUDOERS_DEBUG_PARSER);

    if (v == NULL)
        debug_return_bool(false);

    SLIST_FOREACH(entry, &parser_leak_list, entries) {
        switch (entry->type) {
        case LEAK_PRIVILEGE:
            if (entry->u.p == v)
                goto found;
            break;
        case LEAK_CMNDSPEC:
            if (entry->u.cs == v)
                goto found;
            break;
        case LEAK_DEFAULTS:
            if (entry->u.d == v)
                goto found;
            break;
        case LEAK_MEMBER:
            if (entry->u.m == v)
                goto found;
            break;
        case LEAK_DIGEST:
            if (entry->u.dig == v)
                goto found;
            break;
        case LEAK_RUNAS:
            if (entry->u.rc == v)
                goto found;
            break;
        case LEAK_PTR:
            if (entry->u.ptr == v)
                goto found;
            break;
        default:
            sudo_warnx("unexpected leak type %d in %p", entry->type, entry);
        }
        prev = entry;
    }
    /* If this happens, there is a bug in the leak tracking code. */
    sudo_warnx("%s: unable to find %p, type %d", __func__, v, type);
    return false;
found:
    if (prev == NULL)
        SLIST_REMOVE_HEAD(&parser_leak_list, entries);
    else
        SLIST_REMOVE_AFTER(prev, entries);
    free(entry);
    return true;
#endif /* NO_LEAKS */
}

void
parser_leak_free(void)
{
#ifdef NO_LEAKS
    struct parser_leak_entry *entry;
    void *next;
    debug_decl(parser_leak_run, SUDOERS_DEBUG_PARSER);

    /* Free the leaks. */
    while ((entry = SLIST_FIRST(&parser_leak_list))) {
        SLIST_REMOVE_HEAD(&parser_leak_list, entries);
        switch (entry->type) {
        case LEAK_PRIVILEGE:
            {
                struct privilege *priv;

                HLTQ_FOREACH_SAFE(priv, entry->u.p, entries, next)
                    free_privilege(priv);
                free(entry);
            }
            break;
        case LEAK_CMNDSPEC:
            {
                struct cmndspec_list specs;

                HLTQ_TO_TAILQ(&specs, entry->u.cs, entries);
                free_cmndspecs(&specs);
                free(entry);
            }
            break;
        case LEAK_DEFAULTS:
            {
                struct defaults_list defs;

                HLTQ_TO_TAILQ(&defs, entry->u.d, entries);
                free_defaults(&defs);
                free(entry);
            }
            break;
        case LEAK_MEMBER:
            {
                struct member *m;

                HLTQ_FOREACH_SAFE(m, entry->u.m, entries, next)
                    free_member(m);
                free(entry);
            }
            break;
        case LEAK_DIGEST:
            {
                struct command_digest *dig;

                HLTQ_FOREACH_SAFE(dig, entry->u.dig, entries, next) {
                    free(dig->digest_str);
                    free(dig);
                }
                free(entry);
            }
            break;
        case LEAK_RUNAS:
            {
                struct member *m;

                if (entry->u.rc->runasusers != NULL) {
                    HLTQ_FOREACH_SAFE(m, entry->u.rc->runasusers, entries, next)
                        free_member(m);
                }
                if (entry->u.rc->runasgroups != NULL) {
                    HLTQ_FOREACH_SAFE(m, entry->u.rc->runasgroups, entries, next)
                        free_member(m);
                }
                free(entry->u.rc);
                free(entry);
                break;
            }
        case LEAK_PTR:
            free(entry->u.ptr);
            free(entry);
            break;
        default:
            sudo_warnx("unexpected garbage type %d", entry->type);
        }
    }

    debug_return;
#endif /* NO_LEAKS */
}

void
parser_leak_init(void)
{
#ifdef NO_LEAKS
    static bool initialized;
    debug_decl(parser_leak_init, SUDOERS_DEBUG_PARSER);

    if (!initialized) {
        atexit(parser_leak_free);
        initialized = true;
        debug_return;
    }

    /* Already initialized, free existing leaks. */
    parser_leak_free();
    debug_return;
#endif /* NO_LEAKS */
}

